static int mir_endgame_word_type(int type)
{
    return type_ptr_depth(type) == 0 &&
           (type & 15) == TYPE_INT &&
           type_size(type) == 2;
}

static int mir_endgame_char_pointer_type(int type)
{
    return type_ptr_depth(type) == 1 &&
           (type & 15) == TYPE_CHAR &&
           type_size(type) == 2;
}

static int mir_endgame_opcode_sequence(
    const unsigned char *expected, size_t count)
{
    size_t instruction;

    if ((size_t)mir.count != count)
        return 0;
    for (instruction = 0; instruction < count; ++instruction)
        if (mir.insns[instruction].opcode != expected[instruction])
            return 0;
    return 1;
}

static int mir_endgame_call_arguments(
    const struct MirInsn *call, int arguments[MIR_ENDGAME_MAX_ARGS])
{
    int count = 0;
    int instruction;
    int item;

    for (item = 0; item < MIR_ENDGAME_MAX_ARGS; ++item)
        arguments[item] = -1;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *arg = &mir.insns[instruction];
        int index;

        if (arg->opcode != MIR_ARG ||
            arg->secondary_offset != call->secondary_offset)
            continue;
        index = (int)arg->immediate;
        if (index < 0 || index >= MIR_ENDGAME_MAX_ARGS ||
            arguments[index] >= 0)
            return -1;
        arguments[index] = arg->src1;
        if (index >= count)
            count = index + 1;
    }
    for (item = 0; item < count; ++item)
        if (arguments[item] < 0)
            return -1;
    return count;
}

static struct Sym *mir_endgame_call_function(
    const struct MirInsn *call, int variadic, int fixed_arguments)
{
    struct Sym *function;
    const char *assembly_name;

    if (call->opcode != MIR_CALL || call->src1 >= 0 ||
        ((call->memory_flags & MIR_CALL_FLAG_VARIADIC) != 0) != variadic ||
        (function = find_global(call->name)) == NULL ||
        function->storage != SC_FUNC || function->is_funcptr ||
        function->is_noreturn || !function->has_proto ||
        function->proto_variadic != variadic ||
        function->proto_nargs != fixed_arguments ||
        call->type != function->type)
        return NULL;
    assembly_name = asm_name_for(sym_asm_name(function));
    if (!variadic && call->base_name[0] != 0 &&
        strcmp(call->base_name, assembly_name))
        return NULL;
    if (variadic && call->base_name[0] == 0)
        return NULL;
    return function;
}

static int mir_endgame_constant_bits(
    int value, unsigned long *bits, int *width, int depth)
{
    const struct MirInsn *definition;

    if (depth > 8 || (definition = mir_definition(value)) == NULL)
        return 0;
    if (definition->opcode == MIR_CONST ||
        definition->opcode == MIR_FLOAT_CONST) {
        *width = type_size(definition->type);
        if (*width != 2 && *width != 4)
            return 0;
        *bits = (unsigned long)definition->immediate;
        if (*width == 2)
            *bits &= 0xffffUL;
        return 1;
    }
    if (definition->opcode == MIR_UNARY &&
        definition->immediate == '-' &&
        mir_endgame_constant_bits(
            definition->src1, bits, width, depth + 1)) {
        if (*width == 4 && type_is_float(definition->type))
            *bits ^= 0x80000000UL;
        else
            *bits = (unsigned long)(0UL - *bits);
        return 1;
    }
    return 0;
}

static int mir_endgame_direct_argument(int value)
{
    const struct MirInsn *definition = mir_definition(value);
    unsigned long bits = 0;
    int width = 0;

    return definition != NULL &&
        ((definition->opcode == MIR_STRING_ADDRESS &&
          definition->immediate >= 0 &&
          mir_endgame_char_pointer_type(definition->type)) ||
         mir_endgame_constant_bits(value, &bits, &width, 0));
}

static int mir_endgame_emit_direct_argument(FILE *out, int value)
{
    const struct MirInsn *definition = mir_definition(value);
    unsigned long bits;
    int width;

    if (definition != NULL &&
        definition->opcode == MIR_STRING_ADDRESS) {
        fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
                definition->immediate);
        return 1;
    }
    if (!mir_endgame_constant_bits(value, &bits, &width, 0))
        fatal("invalid endgame direct argument");
    if (width == 4) {
        mir_machine_emit_float_bits(out, bits);
        fputs("\tpush de\n\tpush hl\n", out);
        return 2;
    }
    fprintf(out, "\tld hl,%lu\n\tpush hl\n", bits & 0xffffUL);
    return 1;
}

static const char *mir_endgame_call_name(const struct MirInsn *call)
{
    struct Sym *function = find_global(call->name);

    if (call->base_name[0] != 0)
        return call->base_name;
    if (function == NULL)
        fatal("missing endgame call function");
    return asm_name_for(sym_asm_name(function));
}

static void mir_endgame_emit_direct_call(FILE *out, int instruction)
{
    const struct MirInsn *call = &mir.insns[instruction];
    int arguments[MIR_ENDGAME_MAX_ARGS];
    int argument_count = mir_endgame_call_arguments(call, arguments);
    int words = 0;
    int argument;

    if (argument_count < 0)
        fatal("invalid endgame direct call");
    for (argument = argument_count - 1; argument >= 0; --argument)
        words += mir_endgame_emit_direct_argument(
            out, arguments[argument]);
    if ((call->memory_flags & MIR_CALL_FLAG_FORMAT_HEX) != 0)
        mir_emit_runtime_call(out, "__pfehx");
    if ((call->memory_flags & MIR_CALL_FLAG_FORMAT_OCTAL) != 0)
        mir_emit_runtime_call(out, "__pfeoc");
    mir_emit_runtime_call(out, mir_endgame_call_name(call));
    while (words-- > 0)
        fputs("\tpop bc\n", out);
}

static int mir_endgame_same_address(
    int first_instruction, int second_instruction)
{
    const struct MirInsn *first = &mir.insns[first_instruction];
    const struct MirInsn *second = &mir.insns[second_instruction];

    return first->opcode == MIR_ADDRESS &&
           second->opcode == MIR_ADDRESS &&
           !strcmp(first->name, second->name) &&
           first->type == second->type;
}

static int mir_endgame_call_matches(
    int instruction, struct Sym **function_out, int variadic,
    int fixed_arguments, int argument_count, const int *definitions)
{
    const struct MirInsn *call = &mir.insns[instruction];
    struct Sym *function =
        mir_endgame_call_function(call, variadic, fixed_arguments);
    int arguments[MIR_ENDGAME_MAX_ARGS];
    int argument;

    if (function == NULL ||
        mir_endgame_call_arguments(call, arguments) != argument_count)
        return 0;
    if (*function_out == NULL)
        *function_out = function;
    else if (*function_out != function)
        return 0;
    for (argument = 0; argument < argument_count; ++argument)
        if (definitions != NULL &&
            arguments[argument] !=
                mir.insns[definitions[argument]].dst)
            return 0;
    return 1;
}

static void mir_endgame_emit_frame(FILE *out, int bytes);

static int mir_endgame_strconv_named_memory(
    const struct MirInsn *insn, struct Sym **symbol_out,
    int *storage_out, int *offset_out)
{
    int memory_type;
    int storage;
    int offset;
    struct Sym *symbol;

    if (!mir_machine_named_nonvolatile(insn) ||
        !mir_scalar_memory_location(
            insn, &memory_type, &storage, &offset))
        return 0;
    if (storage == SC_LOCAL)
        symbol = find_local(insn->name);
    else if (storage == SC_GLOBAL || storage == SC_EXTERN)
        symbol = find_global(insn->name);
    else
        return 0;
    if (storage != SC_LOCAL &&
        (symbol == NULL || symbol->is_volatile ||
         symbol->storage != storage))
        return 0;
    *symbol_out = symbol;
    *storage_out = storage;
    *offset_out = offset;
    return 1;
}

static int mir_endgame_strconv_declared_index(const char *name)
{
    int declared;

    for (declared = 0; declared < mir.declared_count; ++declared)
        if (!strcmp(mir.declared_names[declared], name))
            return declared;
    return -1;
}

static int mir_endgame_strconv_value_width(int value)
{
    const struct MirInsn *definition = mir_definition(value);
    int width;

    if (definition == NULL)
        return 0;
    if (definition->opcode == MIR_ADDRESS ||
        definition->opcode == MIR_STRING_ADDRESS)
        return 2;
    width = type_size(definition->type);
    return width == 1 || width == 2 || width == 4 ? width : 0;
}

static int mir_endgame_strconv_value_supported(int value, int depth)
{
    const struct MirInsn *definition;
    struct Sym *symbol;
    int storage;
    int offset;
    int width;
    long constant;

    if (depth > 12 || (definition = mir_definition(value)) == NULL)
        return 0;
    width = mir_endgame_strconv_value_width(value);
    if (width == 0)
        return 0;
    if (mir_machine_evaluate_constant(value, &constant, 0))
        return width == 2 || width == 4;
    switch (definition->opcode) {
    case MIR_STRING_ADDRESS:
        return definition->immediate >= 0 &&
               mir_endgame_char_pointer_type(definition->type);
    case MIR_ADDRESS:
    case MIR_LOAD:
        return mir_endgame_strconv_named_memory(
            definition, &symbol, &storage, &offset);
    case MIR_LOAD_INDIRECT:
        return definition->memory_flags == 0 &&
               definition->memory_size == 1 &&
               mir_endgame_strconv_value_supported(
                   definition->src1, depth + 1);
    case MIR_UNARY:
        return definition->immediate == 0 &&
               width == 2 &&
               mir_endgame_strconv_value_supported(
                   definition->src1, depth + 1);
    case MIR_BINARY:
        return width == 2 &&
               (definition->immediate == TOK_EQ ||
                definition->immediate == TOK_NE) &&
               (mir_machine_constant_equals(definition->src1, 0) ||
                mir_machine_constant_equals(definition->src2, 0)) &&
               mir_endgame_strconv_value_supported(
                   mir_machine_constant_equals(definition->src1, 0)
                       ? definition->src2 : definition->src1,
                   depth + 1);
    case MIR_CALL:
        return definition->src1 < 0 &&
               (width == 2 || width == 4);
    default:
        return 0;
    }
}

static int mir_endgame_strconv_store_for_value(
    int value, int *store_instruction)
{
    int instruction;
    int found = -1;

    for (instruction = 0; instruction < MIR_ENDGAME_STRCONV_LINEAR_END;
         ++instruction) {
        if (mir.insns[instruction].opcode != MIR_STORE ||
            mir.insns[instruction].src1 != value)
            continue;
        if (found >= 0)
            return 0;
        found = instruction;
    }
    *store_instruction = found;
    return 1;
}

static int mir_endgame_strconv_last_argument_use(int value)
{
    int instruction;
    int last = -1;

    for (instruction = 0; instruction < MIR_ENDGAME_STRCONV_LINEAR_END;
         ++instruction)
        if (mir.insns[instruction].opcode == MIR_ARG &&
            mir.insns[instruction].src1 == value)
            last = instruction;
    return last;
}

static int mir_endgame_strconv_value_use_count(int value)
{
    int instruction;
    int uses = 0;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (insn->src1 == value)
            ++uses;
        if (insn->src2 == value)
            ++uses;
    }
    return uses;
}

static struct Sym *mir_endgame_strconv_call_function(
    const struct MirInsn *call)
{
    struct Sym *function;
    int variadic;

    if (call->opcode != MIR_CALL || call->src1 >= 0 ||
        (function = find_global(call->name)) == NULL ||
        function->storage != SC_FUNC || function->is_funcptr ||
        function->is_noreturn || !function->has_proto ||
        call->type != function->type)
        return NULL;
    variadic =
        (call->memory_flags & MIR_CALL_FLAG_VARIADIC) != 0;
    if (function->proto_variadic != variadic)
        return NULL;
    if (!function->is_defined && variadic &&
        call->base_name[0] == 0)
        return NULL;
    if (!variadic && call->base_name[0] != 0 &&
        strcmp(call->base_name,
               asm_name_for(sym_asm_name(function))))
        return NULL;
    return function;
}

static int mir_endgame_strconv_tail(void)
{
    struct Sym *checks = NULL;
    struct Sym *failures = NULL;
    struct Sym *root;
    int arguments[MIR_ENDGAME_MAX_ARGS];
    int storage;
    int checks_offset;
    int failures_offset;
    int offset;

    if (mir.insns[556].opcode != MIR_STRING_ADDRESS ||
        mir.insns[557].opcode != MIR_ARG ||
        mir.insns[557].src1 != mir.insns[556].dst ||
        !mir_endgame_strconv_named_memory(
            &mir.insns[558], &checks, &storage, &checks_offset) ||
        storage != SC_GLOBAL ||
        mir.insns[559].opcode != MIR_ARG ||
        mir.insns[559].src1 != mir.insns[558].dst ||
        !mir_endgame_strconv_named_memory(
            &mir.insns[560], &failures, &storage, &failures_offset) ||
        storage != SC_GLOBAL || checks == failures ||
        mir.insns[561].opcode != MIR_ARG ||
        mir.insns[561].src1 != mir.insns[560].dst ||
        mir_endgame_call_function(&mir.insns[562], 1, 1) == NULL ||
        mir_endgame_call_arguments(&mir.insns[562], arguments) != 3 ||
        arguments[0] != mir.insns[556].dst ||
        arguments[1] != mir.insns[558].dst ||
        arguments[2] != mir.insns[560].dst)
        return 0;
    if (mir.insns[563].opcode != MIR_STRING_ADDRESS ||
        mir.insns[564].opcode != MIR_ARG ||
        !mir_endgame_strconv_named_memory(
            &mir.insns[565], &root, &storage, &offset) ||
        root != failures || storage != SC_GLOBAL ||
        offset != failures_offset ||
        !mir_machine_constant_equals(mir.insns[566].dst, 0) ||
        mir.insns[567].opcode != MIR_BINARY ||
        mir.insns[567].immediate != TOK_EQ ||
        mir.insns[567].src1 != mir.insns[565].dst ||
        mir.insns[567].src2 != mir.insns[566].dst ||
        mir.insns[568].opcode != MIR_BRANCH_FALSE ||
        mir.insns[568].src1 != mir.insns[567].dst ||
        mir.insns[569].opcode != MIR_STRING_ADDRESS ||
        mir.insns[570].opcode != MIR_LABEL ||
        mir.insns[571].opcode != MIR_JUMP ||
        mir.insns[572].opcode != MIR_LABEL ||
        mir.insns[573].opcode != MIR_STRING_ADDRESS ||
        mir.insns[574].opcode != MIR_LABEL ||
        mir.insns[575].opcode != MIR_LABEL ||
        mir.insns[576].opcode != MIR_PHI ||
        mir.insns[576].src1 != mir.insns[569].dst ||
        mir.insns[576].src2 != mir.insns[573].dst ||
        mir.insns[577].opcode != MIR_ARG ||
        mir.insns[577].src1 != mir.insns[576].dst ||
        mir_endgame_call_function(&mir.insns[578], 1, 1) == NULL ||
        mir_endgame_call_arguments(&mir.insns[578], arguments) != 2 ||
        arguments[0] != mir.insns[563].dst ||
        arguments[1] != mir.insns[576].dst)
        return 0;
    return mir.insns[579].opcode == MIR_LOAD &&
           mir_endgame_strconv_named_memory(
               &mir.insns[579], &root, &storage, &offset) &&
           root == failures && storage == SC_GLOBAL &&
           offset == failures_offset &&
           mir.insns[580].opcode == MIR_BRANCH_FALSE &&
           mir.insns[580].src1 == mir.insns[579].dst &&
           mir_machine_constant_equals(mir.insns[581].dst, 1) &&
           mir.insns[582].opcode == MIR_LABEL &&
           mir.insns[583].opcode == MIR_JUMP &&
           mir.insns[584].opcode == MIR_LABEL &&
           mir_machine_constant_equals(mir.insns[585].dst, 0) &&
           mir.insns[586].opcode == MIR_LABEL &&
           mir.insns[587].opcode == MIR_LABEL &&
           mir.insns[588].opcode == MIR_PHI &&
           mir.insns[588].src1 == mir.insns[581].dst &&
           mir.insns[588].src2 == mir.insns[585].dst &&
           mir.insns[589].opcode == MIR_RETURN &&
           mir.insns[589].src1 == mir.insns[588].dst;
}

static int mir_match_endgame_strconv_runner(
    struct MirEndgameStrconvRunner *plan)
{
    static const int expected_array_sizes[6] = {40, 40, 40, 40, 44, 64};
    int arrays[6] = {-1, -1, -1, -1, -1, -1};
    int array_count = 0;
    int opcode_counts[MIR_RETURN + 1];
    int instruction;

    memset(plan, 0, sizeof(*plan));
    memset(opcode_counts, 0, sizeof(opcode_counts));
    if (mir.count != MIR_ENDGAME_STRCONV_INSNS ||
        mir_cfg_block_count() != 9 || mir.local_bytes != 286 ||
        mir.aggregate_temp_bytes != 0 || mir.has_vla ||
        mir.is_variadic_function ||
        !mir_endgame_word_type(mir.return_type) ||
        (mir.return_type & TYPE_UNSIGNED) != 0)
        return mir_machine_reject(
            "endgame-strconv-runner", "shape");
    for (instruction = 0; instruction < mir.count; ++instruction) {
        int opcode = mir.insns[instruction].opcode;

        if (opcode < 0 || opcode > MIR_RETURN)
            return mir_machine_reject(
                "endgame-strconv-runner", "opcode-range");
        ++opcode_counts[opcode];
    }
    if (opcode_counts[MIR_CALL] != 75 ||
        opcode_counts[MIR_ARG] != 214 ||
        opcode_counts[MIR_STRING_ADDRESS] != 80 ||
        opcode_counts[MIR_ADDRESS] != 22 ||
        opcode_counts[MIR_STORE] != 16 ||
        opcode_counts[MIR_LOAD] != 15 ||
        opcode_counts[MIR_LOAD_INDIRECT] != 1 ||
        opcode_counts[MIR_UNARY] != 1 ||
        opcode_counts[MIR_BINARY] != 7 ||
        opcode_counts[MIR_LABEL] != 9 ||
        opcode_counts[MIR_BRANCH_FALSE] != 2 ||
        opcode_counts[MIR_JUMP] != 2 ||
        opcode_counts[MIR_PHI] != 2 ||
        opcode_counts[MIR_RETURN] != 1)
        return mir_machine_reject(
            "endgame-strconv-runner", "opcode-profile");
    for (instruction = 0;
         instruction < MIR_ENDGAME_STRCONV_LINEAR_END; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];
        struct Sym *symbol;
        int arguments[MIR_ENDGAME_MAX_ARGS];
        int argument_count;
        int argument;
        int storage;
        int offset;

        switch (insn->opcode) {
        case MIR_LABEL:
        case MIR_NOP:
        case MIR_CONST:
        case MIR_STRING_ADDRESS:
        case MIR_ARG:
            break;
        case MIR_ADDRESS:
            if (!mir_endgame_strconv_named_memory(
                    insn, &symbol, &storage, &offset) ||
                storage != SC_LOCAL)
                return mir_machine_reject(
                    "endgame-strconv-runner", "address");
            {
                int declared =
                    mir_endgame_strconv_declared_index(insn->name);

                if (declared < 0)
                    return mir_machine_reject(
                        "endgame-strconv-runner", "declaration");
                if (mir.declared_is_array[declared]) {
                    int found = 0;
                    int item;

                    for (item = 0; item < array_count; ++item)
                        if (arrays[item] == declared)
                            found = 1;
                    if (!found) {
                        if (array_count >= 6)
                            return mir_machine_reject(
                                "endgame-strconv-runner",
                                "array-count");
                        arrays[array_count++] = declared;
                    }
                }
            }
            break;
        case MIR_LOAD:
            if (!mir_endgame_strconv_named_memory(
                    insn, &symbol, &storage, &offset) ||
                (mir_endgame_strconv_value_width(insn->dst) != 2 &&
                 mir_endgame_strconv_value_width(insn->dst) != 4))
                return mir_machine_reject(
                    "endgame-strconv-runner", "load");
            break;
        case MIR_STORE:
            if (!mir_endgame_strconv_named_memory(
                    insn, &symbol, &storage, &offset) ||
                (insn->memory_size != 2 &&
                 insn->memory_size != 4) ||
                !mir_endgame_strconv_value_supported(
                    insn->src1, 0))
                return mir_machine_reject(
                    "endgame-strconv-runner", "store");
            break;
        case MIR_LOAD_INDIRECT:
        case MIR_UNARY:
        case MIR_BINARY:
            if (!mir_endgame_strconv_value_supported(
                    insn->dst, 0))
                return mir_machine_reject(
                    "endgame-strconv-runner", "expression");
            break;
        case MIR_CALL:
            {
                struct Sym *function =
                    find_global(insn->name);
                int store_instruction;
                int last_use;
                int width;

                if (function == NULL ||
                    mir_endgame_strconv_call_function(insn) != function ||
                    (argument_count =
                         mir_endgame_call_arguments(
                             insn, arguments)) < 0 ||
                    argument_count > MIR_ENDGAME_MAX_ARGS ||
                    argument_count < function->proto_nargs)
                    return mir_machine_reject(
                        "endgame-strconv-runner", "call");
                for (argument = 0; argument < argument_count;
                     ++argument) {
                    width = mir_endgame_strconv_value_width(
                        arguments[argument]);
                    if ((width != 2 && width != 4) ||
                        !mir_endgame_strconv_value_supported(
                            arguments[argument], 0))
                        return mir_machine_reject(
                            "endgame-strconv-runner", "call-argument");
                }
                if (!mir_endgame_strconv_store_for_value(
                        insn->dst, &store_instruction))
                    return mir_machine_reject(
                        "endgame-strconv-runner", "call-store");
                last_use =
                    mir_endgame_strconv_last_argument_use(insn->dst);
                if (store_instruction < 0 && last_use >= 0) {
                    if (mir_endgame_strconv_value_use_count(
                            insn->dst) != 1)
                        return mir_machine_reject(
                            "endgame-strconv-runner",
                            "deferred-call-use");
                }
            }
            break;
        default:
            return mir_machine_reject(
                "endgame-strconv-runner", "linear-opcode");
        }
    }
    if (array_count != 6)
        return mir_machine_reject(
            "endgame-strconv-runner", "arrays");
    for (instruction = 0; instruction < array_count; ++instruction) {
        int other;
        int rank = 0;

        for (other = 0; other < array_count; ++other)
            if (mir.declared_sizes[arrays[other]] <
                    mir.declared_sizes[arrays[instruction]] ||
                (mir.declared_sizes[arrays[other]] ==
                     mir.declared_sizes[arrays[instruction]] &&
                 other < instruction))
                ++rank;
        if (mir.declared_sizes[arrays[instruction]] !=
                expected_array_sizes[rank] ||
            mir.declared_dim_counts[arrays[instruction]] != 1 ||
            mir.declared_dims[arrays[instruction]][0] !=
                mir.declared_sizes[arrays[instruction]] ||
            mir.declared_elem_sizes[arrays[instruction]] != 1 ||
            (mir.declared_types[arrays[instruction]] & 15) != TYPE_CHAR)
            return mir_machine_reject(
                "endgame-strconv-runner", "array-shape");
    }
    if (!mir_endgame_strconv_tail())
        return mir_machine_reject(
            "endgame-strconv-runner", "tail");
    plan->frame_bytes = mir.local_bytes;
    return 1;
}

static void mir_endgame_strconv_ix_address(FILE *out, int offset)
{
    fputs("\tpush ix\n\tpop hl\n", out);
    if (offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n", offset);
}

static void mir_endgame_strconv_load_at(
    FILE *out, int storage, struct Sym *symbol, int offset, int width)
{
    if (storage == SC_GLOBAL || storage == SC_EXTERN) {
        if (width == 2) {
            mir_machine_emit_global_word(out, symbol, offset);
            return;
        }
        {
            const char *name = asm_name_for(sym_asm_name(symbol));

            if ((symbol->storage == SC_EXTERN || symbol->needs_extrn) &&
                mir_extrn_should_emit(symbol))
                fprintf(out, "\textrn %s\n", name);
            fprintf(out,
                    "\tld hl,(%s%+d)\n\tld de,(%s%+d)\n",
                    name, offset, name, offset + 2);
            return;
        }
    }
    if (offset >= -128 && offset + width - 1 <= 127) {
        if (width == 2)
            fprintf(out,
                    "\tld l,(ix%+d)\n\tld h,(ix%+d)\n",
                    offset, offset + 1);
        else
            fprintf(out,
                    "\tld l,(ix%+d)\n\tld h,(ix%+d)\n"
                    "\tld e,(ix%+d)\n\tld d,(ix%+d)\n",
                    offset, offset + 1, offset + 2, offset + 3);
        return;
    }
    mir_endgame_strconv_ix_address(out, offset);
    if (width == 2) {
        fputs("\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n\tex de,hl\n",
              out);
    } else {
        fputs("\tld c,(hl)\n\tinc hl\n\tld b,(hl)\n"
              "\tinc hl\n\tld e,(hl)\n\tinc hl\n\tld d,(hl)\n"
              "\tld l,c\n\tld h,b\n", out);
    }
}

static void mir_endgame_strconv_store_at(
    FILE *out, int storage, struct Sym *symbol, int offset, int width)
{
    if (storage == SC_GLOBAL || storage == SC_EXTERN) {
        const char *name = asm_name_for(sym_asm_name(symbol));

        if ((symbol->storage == SC_EXTERN || symbol->needs_extrn) &&
            mir_extrn_should_emit(symbol))
            fprintf(out, "\textrn %s\n", name);
        if (width == 2)
            fprintf(out, "\tld (%s%+d),hl\n", name, offset);
        else
            fprintf(out,
                    "\tld (%s%+d),hl\n\tld (%s%+d),de\n",
                    name, offset, name, offset + 2);
        return;
    }
    if (offset >= -128 && offset + width - 1 <= 127) {
        if (width == 2)
            fprintf(out,
                    "\tld (ix%+d),l\n\tld (ix%+d),h\n",
                    offset, offset + 1);
        else
            fprintf(out,
                    "\tld (ix%+d),l\n\tld (ix%+d),h\n"
                    "\tld (ix%+d),e\n\tld (ix%+d),d\n",
                    offset, offset + 1, offset + 2, offset + 3);
        return;
    }
    if (width == 4)
        fputs("\tpush de\n", out);
    fputs("\tpush hl\n", out);
    mir_endgame_strconv_ix_address(out, offset);
    fputs("\tex de,hl\n\tpop hl\n"
          "\tld a,l\n\tld (de),a\n\tinc de\n"
          "\tld a,h\n\tld (de),a\n", out);
    if (width == 4)
        fputs("\tinc de\n\tpop hl\n"
              "\tld a,l\n\tld (de),a\n\tinc de\n"
              "\tld a,h\n\tld (de),a\n", out);
}

static void mir_endgame_strconv_emit_call_target(
    FILE *out, const struct MirInsn *call)
{
    struct Sym *function = find_global(call->name);

    if ((call->memory_flags & MIR_CALL_FLAG_FORMAT_HEX) != 0)
        mir_emit_runtime_call(out, "__pfehx");
    if ((call->memory_flags & MIR_CALL_FLAG_FORMAT_OCTAL) != 0)
        mir_emit_runtime_call(out, "__pfeoc");
    if (function != NULL && function->is_defined &&
        call->base_name[0] == 0)
        mir_machine_emit_symbol_call(out, function);
    else
        mir_emit_runtime_call(out, mir_endgame_call_name(call));
}

static void mir_endgame_strconv_emit_value(
    FILE *out, int value, int *call_offsets,
    int *call_widths);

static void mir_endgame_strconv_emit_deferred_call(
    FILE *out, int instruction, int *call_offsets,
    int *call_widths)
{
    const struct MirInsn *call = &mir.insns[instruction];
    const char *fastcall_name = NULL;
    int arguments[MIR_ENDGAME_MAX_ARGS];
    int argument_count =
        mir_endgame_call_arguments(call, arguments);
    int fastcall_arg0;
    int fastcall_arg1;
    int words = 0;
    int argument;

    if (argument_count < 0)
        fatal("invalid deferred string-conversion call");
    if (mir_call_is_de_hl_fastcall(
            instruction, &fastcall_name,
            &fastcall_arg0, &fastcall_arg1)) {
        mir_endgame_strconv_emit_value(
            out, fastcall_arg0, call_offsets, call_widths);
        fputs("\tpush hl\n", out);
        mir_endgame_strconv_emit_value(
            out, fastcall_arg1, call_offsets, call_widths);
        fputs("\tpop de\n", out);
        mir_emit_runtime_call(out, fastcall_name);
        call_offsets[instruction] =
            MIR_ENDGAME_STRCONV_INLINE_DONE;
        return;
    }
    for (argument = argument_count - 1; argument >= 0; --argument) {
        int width =
            mir_endgame_strconv_value_width(arguments[argument]);

        mir_endgame_strconv_emit_value(
            out, arguments[argument], call_offsets, call_widths);
        if (width == 4) {
            fputs("\tpush de\n\tpush hl\n", out);
            words += 2;
        } else {
            fputs("\tpush hl\n", out);
            ++words;
        }
    }
    mir_endgame_strconv_emit_call_target(out, call);
    while (words-- > 0)
        fputs("\tpop bc\n", out);
    call_offsets[instruction] = MIR_ENDGAME_STRCONV_INLINE_DONE;
}

static void mir_endgame_strconv_emit_value(
    FILE *out, int value, int *call_offsets,
    int *call_widths)
{
    const struct MirInsn *definition = mir_definition(value);
    struct Sym *symbol;
    long constant;
    int storage;
    int offset;
    int width = mir_endgame_strconv_value_width(value);

    if (definition == NULL)
        fatal("missing scheduled string-conversion value");
    if (mir_machine_evaluate_constant(value, &constant, 0)) {
        if (width == 4)
            mir_machine_emit_float_bits(
                out, (unsigned long)constant);
        else
            fprintf(out, "\tld hl,%lu\n",
                    (unsigned long)constant & 0xffffUL);
        return;
    }
    switch (definition->opcode) {
    case MIR_STRING_ADDRESS:
        fprintf(out, "\tld hl,S%ld\n", definition->immediate);
        return;
    case MIR_ADDRESS:
        if (!mir_endgame_strconv_named_memory(
                definition, &symbol, &storage, &offset) ||
            storage != SC_LOCAL)
            fatal("invalid scheduled string-conversion address");
        mir_endgame_strconv_ix_address(out, offset);
        return;
    case MIR_LOAD:
        if (!mir_endgame_strconv_named_memory(
                definition, &symbol, &storage, &offset))
            fatal("invalid scheduled string-conversion load");
        mir_endgame_strconv_load_at(
            out, storage, symbol, offset, width);
        return;
    case MIR_LOAD_INDIRECT:
        mir_endgame_strconv_emit_value(
            out, definition->src1, call_offsets, call_widths);
        fputs("\tld l,(hl)\n\tld h,0\n", out);
        return;
    case MIR_UNARY:
        mir_endgame_strconv_emit_value(
            out, definition->src1, call_offsets, call_widths);
        if ((mir_definition(definition->src1)->type & TYPE_UNSIGNED) == 0 &&
            type_size(mir_definition(definition->src1)->type) == 1) {
            int positive = new_label();

            fputs("\tbit 7,l\n", out);
            fprintf(out,
                    "\tjr z,L%d\n\tdec h\nL%d:\n",
                    positive, positive);
        }
        return;
    case MIR_BINARY:
        {
            int operand =
                mir_machine_constant_equals(definition->src1, 0)
                    ? definition->src2 : definition->src1;
            int nonzero = new_label();
            int done = new_label();

            mir_endgame_strconv_emit_value(
                out, operand, call_offsets, call_widths);
            fputs("\tld a,h\n\tor l\n\tld hl,0\n", out);
            fprintf(out,
                    "\tjr nz,L%d\n\tjr L%d\nL%d:\n\tinc hl\nL%d:\n",
                    nonzero, done, nonzero, done);
            if (definition->immediate == TOK_EQ)
                fputs("\tld a,l\n\txor 1\n\tld l,a\n", out);
        }
        return;
    case MIR_CALL:
        {
            int call_instruction =
                (int)(definition - mir.insns);

            if (call_offsets[call_instruction] ==
                MIR_ENDGAME_STRCONV_DEFERRED) {
                mir_endgame_strconv_emit_deferred_call(
                    out, call_instruction,
                    call_offsets, call_widths);
                return;
            }
            if (call_offsets[call_instruction] == 0 ||
                call_offsets[call_instruction] ==
                    MIR_ENDGAME_STRCONV_INLINE_DONE ||
                call_widths[call_instruction] != width)
                fatal("unsaved scheduled string-conversion call");
            mir_endgame_strconv_load_at(
                out, SC_LOCAL, NULL,
                call_offsets[call_instruction], width);
        }
        return;
    default:
        fatal("unsupported scheduled string-conversion value");
    }
}

static void mir_endgame_strconv_emit_call(
    FILE *out, int instruction, int *call_offsets,
    int *call_widths, unsigned char *consumed_stores)
{
    const struct MirInsn *call = &mir.insns[instruction];
    const char *fastcall_name = NULL;
    int arguments[MIR_ENDGAME_MAX_ARGS];
    int argument_count =
        mir_endgame_call_arguments(call, arguments);
    int fastcall_arg0;
    int fastcall_arg1;
    int words = 0;
    int argument;
    int store_instruction = -1;
    int last_use;
    struct Sym *store_symbol = NULL;
    int store_storage = 0;
    int store_offset = 0;
    int store_width = 0;
    int prepared_store_address = 0;

    if (argument_count < 0)
        fatal("invalid scheduled string-conversion call");
    if (!mir_endgame_strconv_store_for_value(
            call->dst, &store_instruction))
        fatal("ambiguous scheduled string-conversion store");
    if (store_instruction >= 0) {
        if (!mir_endgame_strconv_named_memory(
                &mir.insns[store_instruction],
                &store_symbol, &store_storage, &store_offset))
            fatal("invalid scheduled string-conversion store");
        store_width = mir.insns[store_instruction].memory_size;
        if (store_storage == SC_LOCAL &&
            (store_offset < -128 ||
             store_offset + store_width - 1 > 127)) {
            mir_endgame_strconv_ix_address(out, store_offset);
            fputs("\tpush hl\n", out);
            prepared_store_address = 1;
        }
    }
    if (mir_call_is_de_hl_fastcall(
            instruction, &fastcall_name,
            &fastcall_arg0, &fastcall_arg1)) {
        mir_endgame_strconv_emit_value(
            out, fastcall_arg0, call_offsets, call_widths);
        fputs("\tpush hl\n", out);
        mir_endgame_strconv_emit_value(
            out, fastcall_arg1, call_offsets, call_widths);
        fputs("\tpop de\n", out);
        mir_emit_runtime_call(out, fastcall_name);
    } else {
        for (argument = argument_count - 1;
             argument >= 0; --argument) {
            int argument_width =
                mir_endgame_strconv_value_width(
                    arguments[argument]);

            mir_endgame_strconv_emit_value(
                out, arguments[argument],
                call_offsets, call_widths);
            if (argument_width == 4) {
                fputs("\tpush de\n\tpush hl\n", out);
                words += 2;
            } else {
                fputs("\tpush hl\n", out);
                ++words;
            }
        }
        mir_endgame_strconv_emit_call_target(out, call);
        while (words-- > 0)
            fputs("\tpop bc\n", out);
    }
    last_use = mir_endgame_strconv_last_argument_use(call->dst);
    if (store_instruction >= 0) {
        if (prepared_store_address) {
            if (store_width == 2) {
                fputs("\tex de,hl\n\tpop hl\n"
                      "\tld (hl),e\n\tinc hl\n\tld (hl),d\n",
                      out);
            } else {
                fputs("\tld b,d\n\tld c,e\n\tpop de\n\tex de,hl\n"
                      "\tld (hl),e\n\tinc hl\n\tld (hl),d\n"
                      "\tinc hl\n\tld (hl),c\n\tinc hl\n"
                      "\tld (hl),b\n", out);
            }
        } else {
            mir_endgame_strconv_store_at(
                out, store_storage, store_symbol,
                store_offset, store_width);
        }
        consumed_stores[store_instruction] = 1;
        call_offsets[instruction] = store_offset;
        call_widths[instruction] = store_width;
    } else if (last_use >= 0)
        fatal("undeferred scheduled string-conversion result");
}

static void mir_emit_endgame_strconv_runner(
    FILE *out, const struct MirEndgameStrconvRunner *plan)
{
    int call_offsets[MIR_ENDGAME_STRCONV_INSNS];
    int call_widths[MIR_ENDGAME_STRCONV_INSNS];
    unsigned char consumed_stores[MIR_ENDGAME_STRCONV_INSNS];
    int failure_string = new_label();
    int result_ready = new_label();
    int success = new_label();
    int return_done = new_label();
    int instruction;

    memset(call_offsets, 0, sizeof(call_offsets));
    memset(call_widths, 0, sizeof(call_widths));
    memset(consumed_stores, 0, sizeof(consumed_stores));
    for (instruction = 0;
         instruction < MIR_ENDGAME_STRCONV_LINEAR_END; ++instruction) {
        int store_instruction = -1;

        if (mir.insns[instruction].opcode != MIR_CALL ||
            !mir_endgame_strconv_store_for_value(
                mir.insns[instruction].dst, &store_instruction))
            continue;
        if (store_instruction < 0 &&
            mir_endgame_strconv_last_argument_use(
                mir.insns[instruction].dst) >= 0)
            call_offsets[instruction] =
                MIR_ENDGAME_STRCONV_DEFERRED;
    }
    mir_endgame_emit_frame(out, plan->frame_bytes);
    for (instruction = 0;
         instruction < MIR_ENDGAME_STRCONV_LINEAR_END; ++instruction) {
        const struct MirInsn *insn = &mir.insns[instruction];

        if (insn->opcode == MIR_CALL &&
            call_offsets[instruction] !=
                MIR_ENDGAME_STRCONV_DEFERRED) {
            mir_endgame_strconv_emit_call(
                out, instruction, call_offsets, call_widths,
                consumed_stores);
        } else if (insn->opcode == MIR_STORE &&
                   !consumed_stores[instruction]) {
            struct Sym *symbol;
            int storage;
            int offset;

            if (!mir_endgame_strconv_named_memory(
                    insn, &symbol, &storage, &offset))
                fatal("invalid scheduled string-conversion store");
            mir_endgame_strconv_emit_value(
                out, insn->src1, call_offsets, call_widths);
            mir_endgame_strconv_store_at(
                out, storage, symbol, offset, insn->memory_size);
        }
    }

    mir_endgame_strconv_emit_value(
        out, mir.insns[565].dst, call_offsets, call_widths);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjr nz,L%d\n\tld hl,S%ld\n\tpush hl\n"
            "\tjr L%d\nL%d:\n\tld hl,S%ld\n\tpush hl\n"
            "L%d:\n\tld hl,S%ld\n\tpush hl\n",
            failure_string, mir.insns[569].immediate,
            result_ready, failure_string,
            mir.insns[573].immediate, result_ready,
            mir.insns[563].immediate);
    mir_endgame_strconv_emit_call_target(out, &mir.insns[578]);
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_endgame_strconv_emit_value(
        out, mir.insns[579].dst, call_offsets, call_widths);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out,
            "\tjr z,L%d\n\tld hl,1\n\tjr L%d\n"
            "L%d:\n\tld hl,0\nL%d:\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            success, return_done, success, return_done);
}

static int mir_match_endgame_file_runner(void)
{
    static const int buf_addresses[] = {
        32, 47, 55, 86, 101, 109, 156, 171, 179
    };
    static const int p1_addresses[] = {62, 131};
    static const int p2_addresses[] = {116, 186, 201};
    static const int fgetc_calls[] = {37, 91, 161};
    static const int chkstr_calls[] = {59, 113, 183};
    static const int fgetpos_calls[] = {65, 119, 204};
    static const int chki_calls[] = {74, 128, 143, 198, 213};
    static const int fclose_calls[] = {15, 216};
    static const int fsetpos_calls[] = {134, 189};
    struct Sym *fopen_function = NULL;
    struct Sym *fputs_function = NULL;
    struct Sym *fclose_function = NULL;
    struct Sym *fgetc_function = NULL;
    struct Sym *chkstr_function = NULL;
    struct Sym *fgetpos_function = NULL;
    struct Sym *chki_function = NULL;
    struct Sym *fsetpos_function = NULL;
    struct Sym *remove_function = NULL;
    struct Sym *print_function = NULL;
    int item;

    if (!mir_endgame_opcode_sequence(
            mir_endgame_file_opcodes, sizeof(mir_endgame_file_opcodes)) ||
        mir_cfg_block_count() != 13 || mir.local_bytes != 32 ||
        mir.aggregate_temp_bytes != 0 || mir.has_vla ||
        !mir_endgame_word_type(mir.return_type))
        return mir_machine_reject("endgame-file-runner", "shape");
    for (item = 1;
         item < (int)(sizeof(buf_addresses) / sizeof(buf_addresses[0]));
         ++item)
        if (!mir_endgame_same_address(
                buf_addresses[0], buf_addresses[item]))
            return mir_machine_reject(
                "endgame-file-runner", "buffer");
    for (item = 1;
         item < (int)(sizeof(p1_addresses) / sizeof(p1_addresses[0]));
         ++item)
        if (!mir_endgame_same_address(
                p1_addresses[0], p1_addresses[item]))
            return mir_machine_reject(
                "endgame-file-runner", "first-position");
    for (item = 1;
         item < (int)(sizeof(p2_addresses) / sizeof(p2_addresses[0]));
         ++item)
        if (!mir_endgame_same_address(
                p2_addresses[0], p2_addresses[item]))
            return mir_machine_reject(
                "endgame-file-runner", "second-position");
    if (!strcmp(mir.insns[buf_addresses[0]].name,
                mir.insns[p1_addresses[0]].name) ||
        !strcmp(mir.insns[buf_addresses[0]].name,
                mir.insns[p2_addresses[0]].name) ||
        !strcmp(mir.insns[p1_addresses[0]].name,
                mir.insns[p2_addresses[0]].name) ||
        !mir_endgame_char_pointer_type(
            mir.insns[buf_addresses[0]].type) ||
        type_size(mir.insns[p1_addresses[0]].type) != 2 ||
        type_size(mir.insns[p2_addresses[0]].type) != 2)
        return mir_machine_reject(
            "endgame-file-runner", "local-types");

    if (!mir_endgame_call_matches(
            5, &fopen_function, 0, 2, 2, NULL) ||
        !mir_endgame_call_matches(
            20, &fopen_function, 0, 2, 2, NULL) ||
        !mir_endgame_call_matches(
            12, &fputs_function, 0, 2, 2, NULL) ||
        !mir_endgame_call_matches(
            219, &remove_function, 0, 1, 1, NULL) ||
        !mir_endgame_call_matches(
            227, &print_function, 1, 1, 2, NULL) ||
        !mir_endgame_call_matches(
            232, &print_function, 1, 1, 1, NULL))
        return mir_machine_reject(
            "endgame-file-runner", "calls");
    for (item = 0;
         item < (int)(sizeof(fclose_calls) / sizeof(fclose_calls[0]));
         ++item)
        if (!mir_endgame_call_matches(
                fclose_calls[item], &fclose_function,
                0, 1, 1, NULL))
            return mir_machine_reject(
                "endgame-file-runner", "close-calls");
    for (item = 0;
         item < (int)(sizeof(fgetc_calls) / sizeof(fgetc_calls[0]));
         ++item)
        if (!mir_endgame_call_matches(
                fgetc_calls[item], &fgetc_function,
                0, 1, 1, NULL))
            return mir_machine_reject(
                "endgame-file-runner", "get-calls");
    for (item = 0;
         item < (int)(sizeof(chkstr_calls) / sizeof(chkstr_calls[0]));
         ++item)
        if (!mir_endgame_call_matches(
                chkstr_calls[item], &chkstr_function,
                0, 3, 3, NULL))
            return mir_machine_reject(
                "endgame-file-runner", "string-checks");
    for (item = 0;
         item < (int)(sizeof(fgetpos_calls) / sizeof(fgetpos_calls[0]));
         ++item)
        if (!mir_endgame_call_matches(
                fgetpos_calls[item], &fgetpos_function,
                0, 2, 2, NULL))
            return mir_machine_reject(
                "endgame-file-runner", "get-position");
    for (item = 0;
         item < (int)(sizeof(chki_calls) / sizeof(chki_calls[0]));
         ++item)
        if (!mir_endgame_call_matches(
                chki_calls[item], &chki_function,
                0, 3, 3, NULL))
            return mir_machine_reject(
                "endgame-file-runner", "integer-checks");
    for (item = 0;
         item < (int)(sizeof(fsetpos_calls) / sizeof(fsetpos_calls[0]));
         ++item)
        if (!mir_endgame_call_matches(
                fsetpos_calls[item], &fsetpos_function,
                0, 2, 2, NULL))
            return mir_machine_reject(
                "endgame-file-runner", "set-position");
    if (!mir_machine_constant_equals(mir.insns[23].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[29].dst, 5) ||
        !mir_machine_constant_equals(mir.insns[42].dst, 1) ||
        !mir_machine_constant_equals(mir.insns[48].dst, 5) ||
        !mir_machine_constant_equals(mir.insns[51].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[75].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[83].dst, 6) ||
        !mir_machine_constant_equals(mir.insns[96].dst, 1) ||
        !mir_machine_constant_equals(mir.insns[102].dst, 6) ||
        !mir_machine_constant_equals(mir.insns[105].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[144].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[153].dst, 6) ||
        !mir_machine_constant_equals(mir.insns[166].dst, 1) ||
        !mir_machine_constant_equals(mir.insns[172].dst, 6) ||
        !mir_machine_constant_equals(mir.insns[175].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[234].dst, 0))
        return mir_machine_reject(
            "endgame-file-runner", "constants");
    if (find_global(mir.insns[220].name) == NULL ||
        mir.insns[221].src1 != mir.insns[220].dst)
        return mir_machine_reject(
            "endgame-file-runner", "failure-count");
    return 1;
}

static void mir_endgame_emit_frame(FILE *out, int bytes)
{
    fputs("\tpush ix\n\tld ix,0\n\tadd ix,sp\n", out);
    if (bytes != 0)
        fprintf(out,
                "\tld hl,-%d\n\tadd hl,sp\n\tld sp,hl\n",
                bytes);
    if (opt_stack_check)
        mir_emit_runtime_call(out, "__stchk");
}

static void mir_endgame_emit_ix_address(
    FILE *out, int offset)
{
    fputs("\tpush ix\n\tpop hl\n", out);
    if (offset != 0)
        fprintf(out, "\tld de,%d\n\tadd hl,de\n", offset);
}

static void mir_endgame_emit_symbol_call(
    FILE *out, int instruction)
{
    struct Sym *function = find_global(mir.insns[instruction].name);

    if (function == NULL)
        fatal("missing endgame symbol call");
    mir_machine_emit_symbol_call(out, function);
}

static void mir_endgame_emit_file_read_loop(
    FILE *out, int count, int call_instruction)
{
    int loop = new_label();

    mir_endgame_emit_ix_address(out, -26);
    fprintf(out,
            "\tld (ix-28),l\n\tld (ix-27),h\n"
            "\tld (ix-30),%d\n"
            "L%d:\n\tld l,(ix-28)\n\tld h,(ix-27)\n\tpush hl\n"
            "\tld l,(ix-2)\n\tld h,(ix-1)\n\tpush hl\n",
            count, loop);
    mir_endgame_emit_symbol_call(out, call_instruction);
    fputs("\tpop bc\n\tld a,l\n\tpop de\n\tld (de),a\n"
          "\tinc de\n\tld (ix-28),e\n\tld (ix-27),d\n"
          "\tdec (ix-30)\n", out);
    fprintf(out,
            "\tjp nz,L%d\n\txor a\n\tld (de),a\n",
            loop);
}

static void mir_endgame_emit_string_check(
    FILE *out, int call_instruction,
    int name_instruction, int expected_instruction)
{
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[expected_instruction].immediate);
    mir_endgame_emit_ix_address(out, -26);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[name_instruction].immediate);
    mir_endgame_emit_symbol_call(out, call_instruction);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
}

static void mir_endgame_emit_integer_check(
    FILE *out, int call_instruction,
    int name_instruction)
{
    fputs("\tld hl,0\n\tpush hl\n"
          "\tld l,(ix-30)\n\tld h,(ix-29)\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[name_instruction].immediate);
    mir_endgame_emit_symbol_call(out, call_instruction);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
}

static void mir_endgame_emit_position_call(
    FILE *out, int call_instruction, int position_offset)
{
    mir_endgame_emit_ix_address(out, position_offset);
    fputs("\tpush hl\n\tld l,(ix-2)\n\tld h,(ix-1)\n\tpush hl\n",
          out);
    mir_endgame_emit_symbol_call(out, call_instruction);
    fputs("\tpop bc\n\tpop bc\n"
          "\tld (ix-30),l\n\tld (ix-29),h\n", out);
}

static void mir_emit_endgame_file_runner(FILE *out)
{
    struct Sym *failures = find_global(mir.insns[220].name);
    int success = new_label();
    int done = new_label();

    mir_endgame_emit_frame(out, 30);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[3].immediate);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[1].immediate);
    mir_endgame_emit_symbol_call(out, 5);
    fputs("\tpop bc\n\tpop bc\n\tld (ix-2),l\n\tld (ix-1),h\n",
          out);

    fputs("\tld l,(ix-2)\n\tld h,(ix-1)\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[8].immediate);
    mir_endgame_emit_symbol_call(out, 12);
    fputs("\tpop bc\n\tpop bc\n"
          "\tld l,(ix-2)\n\tld h,(ix-1)\n\tpush hl\n", out);
    mir_endgame_emit_symbol_call(out, 15);
    fputs("\tpop bc\n", out);

    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[18].immediate);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[16].immediate);
    mir_endgame_emit_symbol_call(out, 20);
    fputs("\tpop bc\n\tpop bc\n\tld (ix-2),l\n\tld (ix-1),h\n",
          out);

    mir_endgame_emit_file_read_loop(out, 5, 37);
    mir_endgame_emit_string_check(out, 59, 53, 57);
    mir_endgame_emit_position_call(out, 65, -6);
    mir_endgame_emit_integer_check(out, 74, 68);

    mir_endgame_emit_file_read_loop(out, 6, 91);
    mir_endgame_emit_string_check(out, 113, 107, 111);
    mir_endgame_emit_position_call(out, 119, -10);
    mir_endgame_emit_integer_check(out, 128, 122);

    mir_endgame_emit_position_call(out, 134, -6);
    mir_endgame_emit_integer_check(out, 143, 137);
    mir_endgame_emit_file_read_loop(out, 6, 161);
    mir_endgame_emit_string_check(out, 183, 177, 181);

    mir_endgame_emit_position_call(out, 189, -10);
    mir_endgame_emit_integer_check(out, 198, 192);
    mir_endgame_emit_position_call(out, 204, -10);
    mir_endgame_emit_integer_check(out, 213, 207);

    fputs("\tld l,(ix-2)\n\tld h,(ix-1)\n\tpush hl\n", out);
    mir_endgame_emit_symbol_call(out, 216);
    fputs("\tpop bc\n", out);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[217].immediate);
    mir_endgame_emit_symbol_call(out, 219);
    fputs("\tpop bc\n", out);

    mir_machine_emit_global_word(out, failures, 0);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n\tpush hl\n", success);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[223].immediate);
    mir_emit_runtime_call(out, mir_endgame_call_name(&mir.insns[227]));
    fprintf(out,
            "\tpop bc\n\tpop bc\n\tjp L%d\nL%d:\n",
            done, success);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[230].immediate);
    mir_emit_runtime_call(out, mir_endgame_call_name(&mir.insns[232]));
    fprintf(out,
            "\tpop bc\nL%d:\n\tld hl,0\n"
            "\tld sp,ix\n\tpop ix\n\tret\n",
            done);
}

static int mir_endgame_print_direct_call(
    int instruction, struct Sym **print_function)
{
    const struct MirInsn *call = &mir.insns[instruction];
    int arguments[MIR_ENDGAME_MAX_ARGS];
    int argument_count;
    int argument;

    if (mir_endgame_call_function(call, 1, 1) == NULL ||
        ((argument_count =
              mir_endgame_call_arguments(call, arguments)) < 1) ||
        mir_definition(arguments[0]) == NULL ||
        mir_definition(arguments[0])->opcode != MIR_STRING_ADDRESS ||
        !mir_endgame_char_pointer_type(
            mir_definition(arguments[0])->type))
        return 0;
    if (*print_function == NULL)
        *print_function = find_global(call->name);
    else if (*print_function != find_global(call->name))
        return 0;
    for (argument = 0; argument < argument_count; ++argument)
        if (!mir_endgame_direct_argument(arguments[argument]))
            return 0;
    return 1;
}

static int mir_match_endgame_format_runner(void)
{
    static const int buf_addresses[] = {
        342, 354, 359, 364, 369, 376, 384, 389, 396, 403,
        427, 439, 446, 461, 473, 480, 495, 507, 514
    };
    static const int sbuf_addresses[] = {399, 412};
    static const int vb_addresses[] = {517};
    struct Sym *print_function = NULL;
    struct Sym *strlen_function = NULL;
    struct Sym *sprintf_function = NULL;
    int instruction;
    int direct_calls = 0;
    int item;

    if (!mir_endgame_opcode_sequence(
            mir_endgame_format_opcodes, sizeof(mir_endgame_format_opcodes)) ||
        mir_cfg_block_count() != 13 || mir.local_bytes != 614 ||
        mir.aggregate_temp_bytes != 0 || mir.has_vla ||
        !mir_endgame_word_type(mir.return_type))
        return mir_machine_reject("endgame-format-runner", "shape");
    for (instruction = 0; instruction < 329; ++instruction) {
        if (mir.insns[instruction].opcode != MIR_CALL)
            continue;
        if (!mir_endgame_print_direct_call(
                instruction, &print_function))
            return mir_machine_reject(
                "endgame-format-runner", "direct-call");
        ++direct_calls;
    }
    if (direct_calls != 60)
        return mir_machine_reject(
            "endgame-format-runner", "direct-call-count");
    for (item = 1;
         item < (int)(sizeof(buf_addresses) / sizeof(buf_addresses[0]));
         ++item)
        if (!mir_endgame_same_address(
                buf_addresses[0], buf_addresses[item]))
            return mir_machine_reject(
                "endgame-format-runner", "buffer");
    for (item = 1;
         item < (int)(sizeof(sbuf_addresses) / sizeof(sbuf_addresses[0]));
         ++item)
        if (!mir_endgame_same_address(
                sbuf_addresses[0], sbuf_addresses[item]))
            return mir_machine_reject(
                "endgame-format-runner", "sprintf-buffer");
    if (!strcmp(mir.insns[buf_addresses[0]].name,
                mir.insns[sbuf_addresses[0]].name) ||
        !strcmp(mir.insns[buf_addresses[0]].name,
                mir.insns[vb_addresses[0]].name) ||
        !strcmp(mir.insns[sbuf_addresses[0]].name,
                mir.insns[vb_addresses[0]].name) ||
        !mir_endgame_char_pointer_type(
            mir.insns[buf_addresses[0]].type) ||
        !mir_endgame_char_pointer_type(
            mir.insns[sbuf_addresses[0]].type) ||
        !mir_endgame_char_pointer_type(
            mir.insns[vb_addresses[0]].type))
        return mir_machine_reject(
            "endgame-format-runner", "buffer-types");
    if (!mir_endgame_call_matches(
            378, &strlen_function, 0, 1, 1, NULL) ||
        !mir_endgame_call_matches(
            414, &strlen_function, 0, 1, 1, NULL) ||
        !mir_endgame_call_matches(
            448, &strlen_function, 0, 1, 1, NULL) ||
        !mir_endgame_call_matches(
            482, &strlen_function, 0, 1, 1, NULL) ||
        !mir_endgame_call_matches(
            405, &sprintf_function, 1, 2, 3, NULL) ||
        !mir_endgame_call_matches(
            523, &sprintf_function, 1, 2, 3, NULL))
        return mir_machine_reject(
            "endgame-format-runner", "support-calls");
    {
        static const int later_print_calls[] = {
            381, 386, 393, 398, 417, 451, 485, 516, 530, 534
        };

        for (item = 0;
             item < (int)(sizeof(later_print_calls) /
                          sizeof(later_print_calls[0]));
             ++item) {
            struct Sym *function =
                mir_endgame_call_function(
                    &mir.insns[later_print_calls[item]], 1, 1);
            if (function == NULL || function != print_function)
                return mir_machine_reject(
                    "endgame-format-runner", "later-print");
        }
    }
    if (!mir_machine_constant_equals(mir.insns[333].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[339].dst, 296) ||
        !mir_machine_constant_equals(mir.insns[345].dst, 'a') ||
        !mir_machine_constant_equals(mir.insns[355].dst, 296) ||
        !mir_machine_constant_equals(mir.insns[357].dst, 'x') ||
        !mir_machine_constant_equals(mir.insns[360].dst, 297) ||
        !mir_machine_constant_equals(mir.insns[362].dst, 'y') ||
        !mir_machine_constant_equals(mir.insns[365].dst, 298) ||
        !mir_machine_constant_equals(mir.insns[367].dst, 'z') ||
        !mir_machine_constant_equals(mir.insns[370].dst, 299) ||
        !mir_machine_constant_equals(mir.insns[372].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[424].dst, 255) ||
        !mir_machine_constant_equals(mir.insns[430].dst, 'p') ||
        !mir_machine_constant_equals(mir.insns[440].dst, 255) ||
        !mir_machine_constant_equals(mir.insns[442].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[458].dst, 256) ||
        !mir_machine_constant_equals(mir.insns[464].dst, 'p') ||
        !mir_machine_constant_equals(mir.insns[474].dst, 256) ||
        !mir_machine_constant_equals(mir.insns[476].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[492].dst, 296) ||
        !mir_machine_constant_equals(mir.insns[498].dst, 'a') ||
        !mir_machine_constant_equals(mir.insns[508].dst, 296) ||
        !mir_machine_constant_equals(mir.insns[510].dst, 0) ||
        !mir_machine_constant_equals(mir.insns[535].dst, 0))
        return mir_machine_reject(
            "endgame-format-runner", "buffer-constants");
    return 1;
}

static void mir_endgame_emit_fill(
    FILE *out, int offset, int count, int byte)
{
    int loop = new_label();

    mir_endgame_emit_ix_address(out, offset);
    fprintf(out, "\tld bc,%d\nL%d:\n\tld (hl),%d\n"
                 "\tinc hl\n\tdec bc\n\tld a,b\n\tor c\n"
                 "\tjp nz,L%d\n",
            count, loop, byte & 255, loop);
}

static void mir_endgame_emit_push_ix_address(
    FILE *out, int offset)
{
    mir_endgame_emit_ix_address(out, offset);
    fputs("\tpush hl\n", out);
}

static void mir_endgame_emit_call_cleanup(
    FILE *out, int instruction, int words)
{
    mir_emit_runtime_call(out, mir_endgame_call_name(
        &mir.insns[instruction]));
    while (words-- > 0)
        fputs("\tpop bc\n", out);
}

static void mir_endgame_emit_strlen(
    FILE *out, int call_instruction, int buffer_offset)
{
    mir_endgame_emit_push_ix_address(out, buffer_offset);
    mir_endgame_emit_symbol_call(out, call_instruction);
    fputs("\tpop bc\n", out);
}

static void mir_endgame_emit_format_length(
    FILE *out, int print_instruction,
    int format_instruction, int strlen_instruction,
    int buffer_offset)
{
    mir_endgame_emit_strlen(out, strlen_instruction, buffer_offset);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[format_instruction].immediate);
    mir_endgame_emit_call_cleanup(out, print_instruction, 2);
}

static void mir_endgame_emit_format_buffer(
    FILE *out, int print_instruction,
    int format_instruction, int buffer_offset)
{
    mir_endgame_emit_push_ix_address(out, buffer_offset);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[format_instruction].immediate);
    mir_endgame_emit_call_cleanup(out, print_instruction, 2);
}

static void mir_emit_endgame_format_runner(FILE *out)
{
    int instruction;

    mir_endgame_emit_frame(out, 610);
    for (instruction = 0; instruction < 329; ++instruction)
        if (mir.insns[instruction].opcode == MIR_CALL)
            mir_endgame_emit_direct_call(out, instruction);

    mir_endgame_emit_fill(out, -310, 296, 'a');
    mir_endgame_emit_ix_address(out, -14);
    fputs("\tld (hl),'x'\n\tinc hl\n\tld (hl),'y'\n"
          "\tinc hl\n\tld (hl),'z'\n\tinc hl\n\tld (hl),0\n",
          out);
    mir_endgame_emit_format_length(out, 381, 374, 378, -310);
    mir_endgame_emit_format_buffer(out, 386, 382, -310);
    mir_endgame_emit_ix_address(out, -14);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[387].immediate);
    mir_endgame_emit_call_cleanup(out, 393, 2);
    mir_endgame_emit_format_buffer(out, 398, 394, -310);

    mir_endgame_emit_push_ix_address(out, -310);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[401].immediate);
    mir_endgame_emit_push_ix_address(out, -610);
    mir_endgame_emit_call_cleanup(out, 405, 3);
    fputs("\tld (ix-2),l\n\tld (ix-1),h\n", out);
    mir_endgame_emit_strlen(out, 414, -610);
    fputs("\tpush hl\n\tld l,(ix-2)\n\tld h,(ix-1)\n\tpush hl\n",
          out);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[408].immediate);
    mir_endgame_emit_call_cleanup(out, 417, 3);

    mir_endgame_emit_fill(out, -310, 255, 'p');
    mir_endgame_emit_ix_address(out, -55);
    fputs("\tld (hl),0\n", out);
    mir_endgame_emit_format_length(out, 451, 444, 448, -310);

    mir_endgame_emit_fill(out, -310, 256, 'p');
    mir_endgame_emit_ix_address(out, -54);
    fputs("\tld (hl),0\n", out);
    mir_endgame_emit_format_length(out, 485, 478, 482, -310);

    mir_endgame_emit_fill(out, -310, 296, 'a');
    mir_endgame_emit_ix_address(out, -14);
    fputs("\tld (hl),0\n", out);
    mir_endgame_emit_format_buffer(out, 516, 512, -310);

    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[521].immediate);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[519].immediate);
    mir_endgame_emit_push_ix_address(out, -10);
    mir_endgame_emit_call_cleanup(out, 523, 3);
    fputs("\tld (ix-2),l\n\tld (ix-1),h\n"
          "\tpush hl\n", out);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[526].immediate);
    mir_endgame_emit_call_cleanup(out, 530, 2);
    fprintf(out, "\tld hl,S%ld\n\tpush hl\n",
            mir.insns[532].immediate);
    mir_endgame_emit_call_cleanup(out, 534, 1);
    fputs("\tld hl,0\n\tld sp,ix\n\tpop ix\n\tret\n", out);
}

static int mir_endgame_float_operand(
    int value, int nan_value,
    struct MirEndgameFloatOperand *operand, int depth)
{
    const struct MirInsn *definition;

    if (depth > 8 || (definition = mir_definition(value)) == NULL)
        return 0;
    if (value == nan_value) {
        operand->kind = MIR_ENDGAME_FLOAT_GLOBAL;
        operand->bits = 0;
        return 1;
    }
    if (definition->opcode == MIR_FLOAT_CONST &&
        type_is_float(definition->type) &&
        type_size(definition->type) == 4) {
        operand->kind = MIR_ENDGAME_FLOAT_BITS;
        operand->bits = (unsigned long)definition->immediate;
        return 1;
    }
    if (definition->opcode == MIR_UNARY &&
        definition->immediate == '-' &&
        mir_endgame_float_operand(
            definition->src1, nan_value, operand, depth + 1)) {
        if (operand->kind != MIR_ENDGAME_FLOAT_BITS)
            return 0;
        operand->bits ^= 0x80000000UL;
        return 1;
    }
    return 0;
}

static const char *mir_endgame_float_compare_helper(int operation)
{
    switch (operation) {
    case TOK_EQ: return "__feqf";
    case TOK_NE: return "__fnef";
    case '<': return "__fgtf";
    case '>': return "__fltf";
    case TOK_LE: return "__fgef";
    case TOK_GE: return "__flef";
    default: return NULL;
    }
}

static int mir_endgame_float_helper_index(int operation)
{
    switch (operation) {
    case TOK_EQ: return 0;
    case TOK_NE: return 1;
    case '<': return 2;
    case '>': return 3;
    case TOK_LE: return 4;
    case TOK_GE: return 5;
    default: return -1;
    }
}

static int mir_endgame_match_float_check(
    const struct MirInsn *call, struct Sym **function_out,
    int nan_value, struct MirEndgameFloatCheck *check)
{
    int arguments[MIR_ENDGAME_MAX_ARGS];
    const struct MirInsn *string;
    const struct MirInsn *binary;
    long want;
    struct Sym *function =
        mir_endgame_call_function(call, 0, 3);

    if (function == NULL ||
        mir_endgame_call_arguments(call, arguments) != 3 ||
        (string = mir_definition(arguments[0])) == NULL ||
        string->opcode != MIR_STRING_ADDRESS ||
        string->immediate < 0 ||
        !mir_endgame_char_pointer_type(string->type) ||
        (binary = mir_definition(arguments[1])) == NULL ||
        binary->opcode != MIR_BINARY ||
        !mir_endgame_word_type(binary->type) ||
        mir_endgame_float_compare_helper(
            (int)binary->immediate) == NULL ||
        !mir_endgame_float_operand(
            binary->src1, nan_value, &check->left, 0) ||
        !mir_endgame_float_operand(
            binary->src2, nan_value, &check->right, 0) ||
        !mir_machine_evaluate_constant(
            arguments[2], &want, 0) ||
        (want != 0 && want != 1))
        return 0;
    if (*function_out == NULL)
        *function_out = function;
    else if (*function_out != function)
        return 0;
    check->operation = (int)binary->immediate;
    check->want = (int)want;
    check->string_id = (int)string->immediate;
    return 1;
}

static int mir_match_endgame_float_runner(
    struct MirEndgameFloatRunner *plan)
{
    int instruction;
    int check_count = 0;
    int nan_value;
    unsigned long bits;
    int width;
    struct Sym *print_function = NULL;

    memset(plan, 0, sizeof(*plan));
    if (!mir_endgame_opcode_sequence(
            mir_endgame_float_opcodes, sizeof(mir_endgame_float_opcodes)) ||
        mir_cfg_block_count() != 13 || mir.local_bytes != 40 ||
        mir.aggregate_temp_bytes != 0 || mir.has_vla ||
        !mir_endgame_word_type(mir.return_type) ||
        !type_is_float(mir.insns[5].type) ||
        type_size(mir.insns[5].type) != 4 ||
        (plan->nan_symbol = find_global(mir.insns[5].name)) == NULL)
        return mir_machine_reject("endgame-float-runner", "shape");
    nan_value = mir.insns[5].dst;
    for (instruction = 0; instruction < 573; ++instruction) {
        if (mir.insns[instruction].opcode != MIR_CALL)
            continue;
        if (check_count >= MIR_ENDGAME_FLOAT_CHECKS ||
            !mir_endgame_match_float_check(
                &mir.insns[instruction], &plan->check_function,
                nan_value, &plan->checks_plan[check_count]))
            return mir_machine_reject(
                "endgame-float-runner", "checks");
        ++check_count;
    }
    if (check_count != MIR_ENDGAME_FLOAT_CHECKS)
        return mir_machine_reject(
            "endgame-float-runner", "check-count");
    if (!mir_endgame_constant_bits(
            mir.insns[7].dst, &plan->initial_bits, &width, 0) ||
        width != 4 ||
        !mir_endgame_constant_bits(
            mir.insns[9].dst, &plan->bound_bits, &width, 0) ||
        width != 4 ||
        !mir_endgame_constant_bits(
            mir.insns[589].dst, &plan->step_bits, &width, 0) ||
        width != 4 ||
        !mir_endgame_constant_bits(
            mir.insns[594].dst, &plan->break_bits, &width, 0) ||
        width != 4)
        return mir_machine_reject(
            "endgame-float-runner", "loop-constants");
    if (mir.insns[577].src1 != mir.insns[7].dst ||
        mir.insns[577].src2 != mir.insns[590].dst ||
        mir.insns[586].src1 != mir.insns[577].dst ||
        mir.insns[586].src2 != mir.insns[9].dst ||
        mir.insns[586].immediate != '<' ||
        mir.insns[587].src1 != mir.insns[586].dst ||
        mir.insns[590].src1 != mir.insns[577].dst ||
        mir.insns[590].src2 != mir.insns[589].dst ||
        mir.insns[590].immediate != '+' ||
        mir.insns[595].src1 != mir.insns[590].dst ||
        mir.insns[595].src2 != mir.insns[594].dst ||
        mir.insns[595].immediate != '>' ||
        mir.insns[596].src1 != mir.insns[595].dst ||
        mir.insns[602].label != mir.insns[573].label)
        return mir_machine_reject(
            "endgame-float-runner", "loop");
    {
        int arguments[MIR_ENDGAME_MAX_ARGS];
        const struct MirInsn *string;
        const struct MirInsn *binary;
        long want;

        if (mir_endgame_call_function(
                &mir.insns[612], 0, 3) !=
                plan->check_function ||
            mir_endgame_call_arguments(
                &mir.insns[612], arguments) != 3 ||
            (string = mir_definition(arguments[0])) == NULL ||
            string->opcode != MIR_STRING_ADDRESS ||
            string->immediate < 0 ||
            (binary = mir_definition(arguments[1])) == NULL ||
            binary != &mir.insns[608] ||
            binary->src1 != mir.insns[606].dst ||
            mir.insns[606].opcode != MIR_LOAD ||
            !mir_machine_same_location(
                &mir.insns[606], &mir.insns[592]) ||
            mir_endgame_float_compare_helper(
                (int)binary->immediate) == NULL ||
            !mir_endgame_float_operand(
                binary->src2, nan_value,
                &plan->final_check.right, 0) ||
            !mir_machine_evaluate_constant(
                arguments[2], &want, 0) ||
            (want != 0 && want != 1))
            return mir_machine_reject(
                "endgame-float-runner", "final-check");
        plan->final_check.operation = (int)binary->immediate;
        plan->final_check.want = (int)want;
        plan->final_check.string_id = (int)string->immediate;
    }
    plan->checks = find_global(mir.insns[615].name);
    plan->failures = find_global(mir.insns[617].name);
    if (plan->checks == NULL || plan->failures == NULL ||
        find_global(mir.insns[622].name) != plan->failures ||
        find_global(mir.insns[636].name) != plan->failures ||
        !mir_endgame_call_matches(
            619, &print_function, 1, 1, 3, NULL) ||
        !mir_endgame_call_matches(
            635, &print_function, 1, 1, 2, NULL) ||
        mir.insns[613].opcode != MIR_STRING_ADDRESS ||
        mir.insns[620].opcode != MIR_STRING_ADDRESS ||
        mir.insns[626].opcode != MIR_STRING_ADDRESS ||
        mir.insns[630].opcode != MIR_STRING_ADDRESS ||
        mir.insns[646].src1 != mir.insns[645].dst)
        return mir_machine_reject(
            "endgame-float-runner", "summary");
    plan->summary_string = (int)mir.insns[613].immediate;
    plan->result_string = (int)mir.insns[620].immediate;
    plan->pass_string = (int)mir.insns[626].immediate;
    plan->fail_string = (int)mir.insns[630].immediate;
    snprintf(plan->summary_call, sizeof(plan->summary_call), "%s",
             mir_endgame_call_name(&mir.insns[619]));
    snprintf(plan->result_call, sizeof(plan->result_call), "%s",
             mir_endgame_call_name(&mir.insns[635]));
    if (!mir_endgame_constant_bits(
            mir.insns[638].dst, &bits, &width, 0) ||
        width != 2 || bits != 1 ||
        !mir_endgame_constant_bits(
            mir.insns[642].dst, &bits, &width, 0) ||
        width != 2 || bits != 0)
        return mir_machine_reject(
            "endgame-float-runner", "return-values");
    return 1;
}

static void mir_endgame_emit_global_float(
    FILE *out, struct Sym *symbol)
{
    const char *name = asm_name_for(sym_asm_name(symbol));

    fprintf(out,
            "\tld hl,%s\n"
            "\tld e,(hl)\n"
            "\tinc hl\n"
            "\tld d,(hl)\n"
            "\tinc hl\n"
            "\tld a,(hl)\n"
            "\tinc hl\n"
            "\tld h,(hl)\n"
            "\tld l,a\n"
            "\tex de,hl\n",
            name);
}

static void mir_endgame_emit_float_operand(
    FILE *out, const struct MirEndgameFloatRunner *plan,
    const struct MirEndgameFloatOperand *operand)
{
    if (operand->kind == MIR_ENDGAME_FLOAT_GLOBAL)
        mir_endgame_emit_global_float(out, plan->nan_symbol);
    else
        mir_machine_emit_float_bits(out, operand->bits);
}

static void mir_endgame_emit_float_compare(
    FILE *out, const struct MirEndgameFloatRunner *plan,
    const struct MirEndgameFloatCheck *check,
    const int helper_labels[7])
{
    int helper_index =
        mir_endgame_float_helper_index(check->operation);

    if (helper_index < 0)
        fatal("invalid endgame float comparison");
    mir_endgame_emit_float_operand(out, plan, &check->left);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_endgame_emit_float_operand(out, plan, &check->right);
    fprintf(out, "\tcall L%d\n", helper_labels[helper_index]);
    fputs("\tpop bc\n\tpop bc\n", out);
}

static void mir_endgame_emit_float_check(
    FILE *out, const struct MirEndgameFloatRunner *plan,
    const struct MirEndgameFloatCheck *check,
    const int helper_labels[7])
{
    fprintf(out, "\tld hl,%d\n\tpush hl\n", check->want);
    mir_endgame_emit_float_compare(
        out, plan, check, helper_labels);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n", check->string_id);
    mir_machine_emit_symbol_call(out, plan->check_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);
}

static void mir_emit_endgame_float_runner(
    FILE *out, const struct MirEndgameFloatRunner *plan)
{
    const char *nan_name =
        asm_name_for(sym_asm_name(plan->nan_symbol));
    int loop = new_label();
    int done = new_label();
    int no_break = new_label();
    int pass = new_label();
    int string_done = new_label();
    int return_done = new_label();
    int body = new_label();
    int helper_labels[7];
    int check;
    static const char *const helpers[7] = {
        "__feqf", "__fnef", "__fgtf", "__fltf",
        "__fgef", "__flef", "__faf"
    };

    for (check = 0; check < 7; ++check)
        helper_labels[check] = new_label();
    fprintf(out, "\tjp L%d\n", body);
    for (check = 0; check < 7; ++check) {
        if (mir_extrn_should_emit_name(helpers[check]))
            fprintf(out, "\textrn %s\n", helpers[check]);
        fprintf(out, "L%d:\n\tjp %s\n",
                helper_labels[check], helpers[check]);
    }
    fprintf(out, "L%d:\n", body);
    if ((plan->nan_symbol->storage == SC_EXTERN ||
         plan->nan_symbol->needs_extrn) &&
        mir_extrn_should_emit(plan->nan_symbol))
        fprintf(out, "\textrn %s\n", nan_name);
    mir_endgame_emit_frame(out, 4);
    mir_machine_emit_float_bits(out, plan->initial_bits);
    mir_machine_emit_ix_wide_store(out, -4);
    for (check = 0; check < MIR_ENDGAME_FLOAT_CHECKS; ++check)
        mir_endgame_emit_float_check(
            out, plan, &plan->checks_plan[check],
            helper_labels);

    fprintf(out, "L%d:\n", loop);
    mir_machine_emit_ix_wide_load(out, -4);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_machine_emit_float_bits(out, plan->bound_bits);
    fprintf(out, "\tcall L%d\n", helper_labels[2]);
    fputs("\tpop bc\n\tpop bc\n\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n", done);

    mir_machine_emit_ix_wide_load(out, -4);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_machine_emit_float_bits(out, plan->step_bits);
    fprintf(out, "\tcall L%d\n", helper_labels[6]);
    fputs("\tpop bc\n\tpop bc\n", out);
    mir_machine_emit_ix_wide_store(out, -4);

    fputs("\tpush de\n\tpush hl\n", out);
    mir_machine_emit_float_bits(out, plan->break_bits);
    fprintf(out, "\tcall L%d\n", helper_labels[3]);
    fputs("\tpop bc\n\tpop bc\n\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n\tjp L%d\nL%d:\n",
            no_break, done, no_break);
    fprintf(out, "\tjp L%d\nL%d:\n", loop, done);

    fprintf(out, "\tld hl,%d\n\tpush hl\n",
            plan->final_check.want);
    mir_machine_emit_ix_wide_load(out, -4);
    fputs("\tpush de\n\tpush hl\n", out);
    mir_endgame_emit_float_operand(
        out, plan, &plan->final_check.right);
    fprintf(out, "\tcall L%d\n",
            helper_labels[
                mir_endgame_float_helper_index(
                    plan->final_check.operation)]);
    fputs("\tpop bc\n\tpop bc\n\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->final_check.string_id);
    mir_machine_emit_symbol_call(out, plan->check_function);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);

    mir_machine_emit_global_word(out, plan->failures, 0);
    fputs("\tpush hl\n", out);
    mir_machine_emit_global_word(out, plan->checks, 0);
    fputs("\tpush hl\n", out);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->summary_string);
    mir_emit_runtime_call(out, plan->summary_call);
    fputs("\tpop bc\n\tpop bc\n\tpop bc\n", out);

    mir_machine_emit_global_word(out, plan->failures, 0);
    fputs("\tld a,h\n\tor l\n", out);
    fprintf(out, "\tjp z,L%d\n\tld hl,S%d\n\tjp L%d\n"
                 "L%d:\n\tld hl,S%d\nL%d:\n\tpush hl\n",
            pass, plan->fail_string, string_done,
            pass, plan->pass_string, string_done);
    fprintf(out, "\tld hl,S%d\n\tpush hl\n",
            plan->result_string);
    mir_emit_runtime_call(out, plan->result_call);
    fputs("\tpop bc\n\tpop bc\n", out);

    mir_machine_emit_global_word(out, plan->failures, 0);
    fputs("\tld a,h\n\tor l\n\tld hl,0\n", out);
    fprintf(out, "\tjp z,L%d\n\tinc hl\nL%d:\n"
                 "\tld sp,ix\n\tpop ix\n\tret\n",
            return_done, return_done);
}

static int mir_endgame_width_integer_type(
    int type, int base, int is_unsigned, int width)
{
    return type_ptr_depth(type) == 0 &&
           (type & 15) == base &&
           ((type & TYPE_UNSIGNED) != 0) == is_unsigned &&
           type_size(type) == width;
}

static int mir_endgame_width_binary(
    int instruction, int operation, int result_type,
    int operand_type, int left, int right)
{
    const struct MirInsn *binary = &mir.insns[instruction];

    return binary->opcode == MIR_BINARY &&
           binary->immediate == operation &&
           binary->type == result_type &&
           binary->secondary_offset == operand_type &&
           binary->src1 == mir.insns[left].dst &&
           binary->src2 == mir.insns[right].dst;
}

static int mir_endgame_width_unary(
    int instruction, int result_type, int source)
{
    const struct MirInsn *unary = &mir.insns[instruction];

    return unary->opcode == MIR_UNARY &&
           unary->immediate == 0 &&
           unary->type == result_type &&
           unary->src1 == mir.insns[source].dst;
}

static int mir_endgame_width_boolean(int instruction, int *result)
{
    long evaluated;

    if (!mir_machine_evaluate_constant(
            mir.insns[instruction].dst, &evaluated, 0) ||
        (evaluated != 0 && evaluated != 1))
        return 0;
    *result = evaluated != 0;
    return 1;
}

static int mir_endgame_numeric_graph(void)
{
    static const int branch_values[][2] = {
        {15, 14}, {36, 35}, {57, 56}, {78, 77}, {99, 98},
        {120, 119}, {141, 140}, {162, 161}, {183, 182}
    };
    size_t item;

    for (item = 0;
         item < sizeof(mir_endgame_numeric_edges) /
                sizeof(mir_endgame_numeric_edges[0]);
         ++item) {
        const struct MirEndgameWidthEdge *edge =
            &mir_endgame_numeric_edges[item];

        if ((mir.insns[edge->instruction].opcode !=
                 MIR_BRANCH_FALSE &&
             mir.insns[edge->instruction].opcode != MIR_JUMP) ||
            mir.insns[edge->instruction].label !=
                mir.insns[edge->target].label)
            return 0;
    }
    for (item = 0;
         item < sizeof(mir_endgame_numeric_phis) /
                sizeof(mir_endgame_numeric_phis[0]);
         ++item) {
        const struct MirEndgameWidthPhi *phi =
            &mir_endgame_numeric_phis[item];
        const struct MirInsn *instruction =
            &mir.insns[phi->instruction];

        if (instruction->opcode != MIR_PHI ||
            instruction->src1 !=
                mir.insns[phi->first_value].dst ||
            instruction->src2 !=
                mir.insns[phi->second_value].dst ||
            instruction->phi_pred1 !=
                mir.insns[phi->first_predecessor].label ||
            instruction->phi_pred2 !=
                mir.insns[phi->second_predecessor].label)
            return 0;
    }
    for (item = 0;
         item < sizeof(branch_values) / sizeof(branch_values[0]);
         ++item)
        if (mir.insns[branch_values[item][0]].src1 !=
            mir.insns[branch_values[item][1]].dst)
            return 0;
    return 1;
}

static int mir_endgame_numeric_objects(void)
{
    static const int locations[] = {
        3, 11, 16, 32, 37, 53, 58, 74, 79, 95,
        100, 116, 121, 137, 142, 158, 163, 179, 184
    };
    int memory_type;
    int memory_storage;
    int memory_offset;
    size_t item;

    if (mir.object_count != 0 ||
        !mir_machine_named_nonvolatile(&mir.insns[locations[0]]) ||
        !mir_scalar_memory_location(
            &mir.insns[locations[0]], &memory_type,
            &memory_storage, &memory_offset) ||
        memory_storage != SC_LOCAL || memory_offset != -2 ||
        !mir_endgame_width_integer_type(
            memory_type, TYPE_INT, 1, 2))
        return 0;
    for (item = 1;
         item < sizeof(locations) / sizeof(locations[0]);
         ++item) {
        const struct MirInsn *location =
            &mir.insns[locations[item]];

        if (!mir_machine_named_nonvolatile(location) ||
            !mir_machine_same_location(
                &mir.insns[locations[0]],
                location))
            return 0;
    }
    for (item = 0;
         item < sizeof(locations) / sizeof(locations[0]);
         ++item) {
        const struct MirInsn *location =
            &mir.insns[locations[item]];

        if (location->opcode == MIR_ADDRESS) {
            if (type_ptr_depth(location->type) != 1 ||
                (location->type & 15) != TYPE_INT ||
                (location->type & TYPE_UNSIGNED) == 0 ||
                type_size(location->type) != 2)
                return 0;
        } else if (location->opcode == MIR_LOAD) {
            if (!mir_endgame_width_integer_type(
                    location->type, TYPE_INT, 1, 2))
                return 0;
        } else if (location->opcode == MIR_STORE) {
            if (location->memory_size != 2)
                return 0;
        } else {
            return 0;
        }
    }
    return mir.insns[3].src1 == mir.insns[1].dst;
}

static int mir_endgame_numeric_operations(
    struct MirEndgameNumericRunner *plan)
{
    static const struct {
        int instruction;
        long value;
    } constants[] = {
        {1, 0},
        {22, 65535}, {43, 65535}, {64, 65535},
        {85, 65535}, {106, 65535}, {127, 65535},
        {148, 65535}, {169, 65535}, {190, 65535},
        {198, 0}, {201, 1}, {209, 0}, {212, 4},
        {220, 511}, {223, 1}, {231, 1}, {234, 511},
        {242, 0}, {245, 511}, {254, 0}
    };
    static const int string_instructions[] = {
        4, 7, 9, 28, 30, 49, 51, 70, 72, 91,
        93, 112, 114, 133, 135, 154, 156, 175, 177,
        196, 207, 218, 229, 240, 251
    };
    size_t item;

    for (item = 0;
         item < sizeof(constants) / sizeof(constants[0]);
         ++item)
        if (!mir_machine_constant_equals(
                mir.insns[constants[item].instruction].dst,
                constants[item].value) ||
            !mir_endgame_width_integer_type(
                mir.insns[constants[item].instruction].type,
                TYPE_INT, 0, 2))
            return 0;
    for (item = 0;
         item < sizeof(string_instructions) /
                sizeof(string_instructions[0]);
         ++item) {
        const struct MirInsn *string =
            &mir.insns[string_instructions[item]];
        size_t earlier;

        if (string->immediate < 0 ||
            !mir_endgame_char_pointer_type(string->type))
            return 0;
        plan->strings[item] = (int)string->immediate;
        for (earlier = 0; earlier < item; ++earlier)
            if (plan->strings[item] == plan->strings[earlier])
                return 0;
    }
    for (item = 0;
         item < sizeof(mir_endgame_numeric_phis) /
                sizeof(mir_endgame_numeric_phis[0]);
         ++item)
        if (!mir_endgame_width_integer_type(
                mir.insns[
                    mir_endgame_numeric_phis[item].instruction].type,
                TYPE_INT, 0, 2))
            return 0;
    return mir.insns[255].src1 == mir.insns[254].dst;
}

static int mir_endgame_numeric_calls(
    struct MirEndgameNumericRunner *plan)
{
    static const int parse_steps[MIR_ENDGAME_NUMERIC_PARSE_CASES][7] = {
        {14, 27, 7, 9, 11, 16, 25},
        {35, 48, 28, 30, 32, 37, 46},
        {56, 69, 49, 51, 53, 58, 67},
        {77, 90, 70, 72, 74, 79, 88},
        {98, 111, 91, 93, 95, 100, 109},
        {119, 132, 112, 114, 116, 121, 130},
        {140, 153, 133, 135, 137, 142, 151},
        {161, 174, 154, 156, 158, 163, 172},
        {182, 195, 175, 177, 179, 184, 193}
    };
    static const int visit_steps[MIR_ENDGAME_NUMERIC_VISIT_CASES][5] = {
        {204, 206, 196, 198, 201},
        {215, 217, 207, 209, 212},
        {226, 228, 218, 220, 223},
        {237, 239, 229, 231, 234},
        {248, 250, 240, 242, 245}
    };
    int print_call = 0;
    int call_count = 0;
    int arguments[2];
    int instruction;
    int item;

    arguments[0] = 4;
    if (!mir_endgame_call_matches(
            6, &plan->print_function, 1, 1, 1, arguments))
        return 0;
    snprintf(plan->print_names[print_call++],
        sizeof(plan->print_names[0]), "%s",
        mir_endgame_call_name(&mir.insns[6]));

    for (item = 0; item < MIR_ENDGAME_NUMERIC_PARSE_CASES; ++item) {
        const int *step = parse_steps[item];

        arguments[0] = step[3];
        arguments[1] = step[4];
        if (!mir_endgame_call_matches(
                step[0], &plan->parse_function,
                0, 2, 2, arguments))
            return 0;
        arguments[0] = step[2];
        arguments[1] = step[6];
        if (!mir_endgame_call_matches(
                step[1], &plan->print_function,
                1, 1, 2, arguments))
            return 0;
        if (mir.insns[step[5]].opcode != MIR_LOAD ||
            mir.insns[step[6]].src1 !=
                mir.insns[step[5]].dst)
            return 0;
        snprintf(plan->print_names[print_call++],
            sizeof(plan->print_names[0]), "%s",
            mir_endgame_call_name(&mir.insns[step[1]]));
    }

    for (item = 0; item < MIR_ENDGAME_NUMERIC_VISIT_CASES; ++item) {
        const int *step = visit_steps[item];

        arguments[0] = step[3];
        arguments[1] = step[4];
        if (!mir_endgame_call_matches(
                step[0], &plan->visit_function,
                0, 2, 2, arguments))
            return 0;
        arguments[0] = step[2];
        arguments[1] = step[0];
        if (!mir_endgame_call_matches(
                step[1], &plan->print_function,
                1, 1, 2, arguments))
            return 0;
        snprintf(plan->print_names[print_call++],
            sizeof(plan->print_names[0]), "%s",
            mir_endgame_call_name(&mir.insns[step[1]]));
    }

    arguments[0] = 251;
    if (!mir_endgame_call_matches(
            253, &plan->print_function, 1, 1, 1, arguments))
        return 0;
    snprintf(plan->print_names[print_call++],
        sizeof(plan->print_names[0]), "%s",
        mir_endgame_call_name(&mir.insns[253]));

    if (print_call != MIR_ENDGAME_NUMERIC_PRINT_CALLS ||
        plan->parse_function == plan->visit_function ||
        plan->parse_function == plan->print_function ||
        plan->visit_function == plan->print_function ||
        !mir_endgame_width_integer_type(
            plan->parse_function->type, TYPE_INT, 0, 2) ||
        !mir_endgame_char_pointer_type(
            plan->parse_function->proto_types[0]) ||
        type_ptr_depth(
            plan->parse_function->proto_types[1]) != 1 ||
        (plan->parse_function->proto_types[1] & 15) != TYPE_INT ||
        (plan->parse_function->proto_types[1] & TYPE_UNSIGNED) == 0 ||
        type_size(plan->parse_function->proto_types[1]) != 2 ||
        !mir_endgame_width_integer_type(
            plan->visit_function->type, TYPE_INT, 1, 2) ||
        !mir_endgame_width_integer_type(
            plan->visit_function->proto_types[0], TYPE_INT, 1, 2) ||
        !mir_endgame_width_integer_type(
            plan->visit_function->proto_types[1], TYPE_INT, 1, 2) ||
        !mir_endgame_width_integer_type(
            plan->print_function->type, TYPE_INT, 0, 2) ||
        !mir_endgame_char_pointer_type(
            plan->print_function->proto_types[0]))
        return 0;

    for (instruction = 0; instruction < mir.count; ++instruction) {
        if (mir.insns[instruction].opcode == MIR_CALL)
            ++call_count;
        if (mir.insns[instruction].opcode == MIR_CALL &&
            (mir.insns[instruction].memory_flags &
             (MIR_CALL_FLAG_FORMAT_HEX |
              MIR_CALL_FLAG_FORMAT_OCTAL)) != 0)
            return 0;
    }
    return call_count == 30;
}

static int mir_match_endgame_numeric_runner(
    struct MirEndgameNumericRunner *plan)
{
    memset(plan, 0, sizeof(*plan));
    if (!mir_endgame_opcode_sequence(
            mir_endgame_numeric_opcodes,
            sizeof(mir_endgame_numeric_opcodes)) ||
        mir_cfg_block_count() != 37 ||
        mir.local_bytes != 2 ||
        mir.aggregate_temp_bytes != 0 ||
        mir.has_vla || mir.is_variadic_function ||
        !mir_endgame_width_integer_type(
            mir.return_type, TYPE_INT, 0, 2))
        return mir_machine_reject(
            "endgame-numeric-runner", "shape");
    if (!mir_endgame_numeric_graph())
        return mir_machine_reject(
            "endgame-numeric-runner", "graph");
    if (!mir_endgame_numeric_objects())
        return mir_machine_reject(
            "endgame-numeric-runner", "objects");
    if (!mir_endgame_numeric_operations(plan))
        return mir_machine_reject(
            "endgame-numeric-runner", "operations");
    if (!mir_endgame_numeric_calls(plan))
        return mir_machine_reject(
            "endgame-numeric-runner", "calls");
    return 1;
}

static int mir_endgame_binary_link(
    int instruction, int operation, int left, int right)
{
    const struct MirInsn *binary = &mir.insns[instruction];

    return binary->opcode == MIR_BINARY &&
           binary->immediate == operation &&
           binary->src1 == mir.insns[left].dst &&
           binary->src2 == mir.insns[right].dst;
}

static int mir_endgame_unary_link(
    int instruction, int type, int source)
{
    const struct MirInsn *unary = &mir.insns[instruction];

    return unary->opcode == MIR_UNARY &&
           unary->immediate == 0 &&
           unary->type == type &&
           unary->src1 == mir.insns[source].dst;
}

static int mir_endgame_binary_opcode_sequence(void)
{
    size_t next = 0;
    int instruction;

    if (mir.count != 461)
        return 0;
    for (instruction = 0; instruction < mir.count; ++instruction) {
        int expected = MIR_NOP;

        if (next < sizeof(mir_endgame_binary_opcodes) /
                   sizeof(mir_endgame_binary_opcodes[0]) &&
            mir_endgame_binary_opcodes[next].instruction == instruction) {
            expected = mir_endgame_binary_opcodes[next].opcode;
            ++next;
        }
        if (mir.insns[instruction].opcode != expected)
            return 0;
    }
    return next == sizeof(mir_endgame_binary_opcodes) /
                   sizeof(mir_endgame_binary_opcodes[0]);
}

static int mir_endgame_binary_graph(void)
{
    static const int branch_values[][2] = {
        {107, 106}, {134, 133}, {180, 179}, {198, 197},
        {250, 249}, {272, 271}, {279, 278}, {287, 286},
        {353, 352}, {389, 388}, {404, 403}, {412, 411},
        {424, 423}
    };
    size_t item;

    for (item = 0;
         item < sizeof(mir_endgame_binary_edges) /
                sizeof(mir_endgame_binary_edges[0]);
         ++item) {
        const struct MirEndgameWidthEdge *edge =
            &mir_endgame_binary_edges[item];

        if ((mir.insns[edge->instruction].opcode !=
                 MIR_BRANCH_FALSE &&
             mir.insns[edge->instruction].opcode != MIR_JUMP) ||
            mir.insns[edge->instruction].label !=
                mir.insns[edge->target].label)
            return 0;
    }
    for (item = 0;
         item < sizeof(mir_endgame_binary_phis) /
                sizeof(mir_endgame_binary_phis[0]);
         ++item) {
        const struct MirEndgameWidthPhi *phi =
            &mir_endgame_binary_phis[item];
        const struct MirInsn *instruction =
            &mir.insns[phi->instruction];

        if (instruction->opcode != MIR_PHI ||
            instruction->src1 !=
                mir.insns[phi->first_value].dst ||
            instruction->src2 !=
                mir.insns[phi->second_value].dst ||
            instruction->phi_pred1 !=
                mir.insns[phi->first_predecessor].label ||
            instruction->phi_pred2 !=
                mir.insns[phi->second_predecessor].label)
            return 0;
    }
    for (item = 0;
         item < sizeof(branch_values) / sizeof(branch_values[0]);
         ++item)
        if (mir.insns[branch_values[item][0]].src1 !=
            mir.insns[branch_values[item][1]].dst)
            return 0;
    return 1;
}

static int mir_endgame_same_locations(
    const int *instructions, size_t count, int width)
{
    size_t item;

    if (count == 0 ||
        !mir_machine_named_nonvolatile(
            &mir.insns[instructions[0]]))
        return 0;
    for (item = 0; item < count; ++item) {
        const struct MirInsn *location =
            &mir.insns[instructions[item]];
        int location_width =
            location->opcode == MIR_LOAD
                ? type_size(location->type)
                : location->memory_size;

        if (!mir_machine_named_nonvolatile(
                location) ||
            location_width != width ||
            !mir_machine_same_location(
                &mir.insns[instructions[0]],
                location))
            return 0;
    }
    return 1;
}

static int mir_endgame_binary_objects(
    struct MirEndgameBinaryRunner *plan)
{
    static const int offset_locations[] = {6, 448};
    static const int indent_index_locations[] = {114, 131, 142, 145};
    static const int line_pointer_locations[] = {
        110, 135, 138, 148, 155, 156, 159, 162, 165,
        251, 262, 263, 266, 288, 291, 294, 297,
        354, 357, 429, 432, 449
    };
    static const int extra_space_locations[] = {227, 302, 314};
    static const int hex_index_locations[] = {230, 310};
    static const int space_index_locations[] = {331, 364};
    static const int text_index_locations[] = {369, 440};
    static const int character_locations[] = {398, 427, 433};
    const struct MirInsn *line = &mir.insns[109];
    const struct MirInsn *bytes = &mir.insns[213];
    const struct MirInsn *parameter;
    int item;

    for (item = 0; item < 3; ++item) {
        parameter = &mir.insns[item + 1];
        if (!mir_machine_parameter_value_offset(
                parameter->dst, &plan->parameter_offsets[item]))
            return 0;
    }
    if (plan->parameter_offsets[0] != 2 ||
        plan->parameter_offsets[1] != 4 ||
        plan->parameter_offsets[2] != 6 ||
        type_ptr_depth(mir.insns[1].type) != 1 ||
        (mir.insns[1].type & 15) != TYPE_CHAR ||
        (mir.insns[1].type & TYPE_UNSIGNED) == 0 ||
        type_size(mir.insns[1].type) != 2 ||
        mir_machine_pointee_is_volatile(&mir.insns[1]) ||
        !mir_endgame_width_integer_type(
            mir.insns[2].type, TYPE_INT, 1, 2) ||
        mir.insns[3].type != mir.insns[2].type)
        return 0;

    plan->line_buffer = find_global(line->name);
    plan->byte_buffer = find_global(bytes->name);
    if (line->opcode != MIR_ADDRESS ||
        bytes->opcode != MIR_ADDRESS ||
        plan->line_buffer == NULL ||
        plan->byte_buffer == NULL ||
        plan->line_buffer == plan->byte_buffer ||
        !plan->line_buffer->is_defined ||
        !plan->byte_buffer->is_defined ||
        plan->line_buffer->is_volatile ||
        plan->byte_buffer->is_volatile ||
        !plan->line_buffer->is_array ||
        !plan->byte_buffer->is_array ||
        plan->line_buffer->dim_count != 1 ||
        plan->byte_buffer->dim_count != 1 ||
        plan->line_buffer->dims[0] != 200 ||
        plan->byte_buffer->dims[0] != 32 ||
        plan->line_buffer->array_len != 200 ||
        plan->byte_buffer->array_len != 32 ||
        plan->line_buffer->elem_size != 1 ||
        plan->byte_buffer->elem_size != 1 ||
        (plan->line_buffer->type & 15) != TYPE_CHAR ||
        (plan->line_buffer->type & TYPE_UNSIGNED) != 0 ||
        (plan->byte_buffer->type & 15) != TYPE_CHAR ||
        (plan->byte_buffer->type & TYPE_UNSIGNED) == 0 ||
        type_size(plan->line_buffer->type) != 1 ||
        type_size(plan->byte_buffer->type) != 1 ||
        type_ptr_depth(line->type) != 1 ||
        type_ptr_depth(bytes->type) != 1)
        return 0;
    if (find_global(mir.insns[253].name) != plan->byte_buffer ||
        find_global(mir.insns[391].name) != plan->byte_buffer ||
        find_global(mir.insns[454].name) != plan->line_buffer)
        return 0;
    return mir_endgame_same_locations(
               offset_locations,
               sizeof(offset_locations) / sizeof(offset_locations[0]), 2) &&
           mir_endgame_same_locations(
               indent_index_locations,
               sizeof(indent_index_locations) /
                   sizeof(indent_index_locations[0]), 2) &&
           mir_endgame_same_locations(
               line_pointer_locations,
               sizeof(line_pointer_locations) /
                   sizeof(line_pointer_locations[0]), 2) &&
           mir_endgame_same_locations(
               extra_space_locations,
               sizeof(extra_space_locations) /
                   sizeof(extra_space_locations[0]), 4) &&
           mir_endgame_same_locations(
               hex_index_locations,
               sizeof(hex_index_locations) /
                   sizeof(hex_index_locations[0]), 2) &&
           mir_endgame_same_locations(
               space_index_locations,
               sizeof(space_index_locations) /
                   sizeof(space_index_locations[0]), 2) &&
           mir_endgame_same_locations(
               text_index_locations,
               sizeof(text_index_locations) /
                   sizeof(text_index_locations[0]), 2) &&
           mir_endgame_same_locations(
               character_locations,
               sizeof(character_locations) /
                   sizeof(character_locations[0]), 1) &&
           mir_machine_named_nonvolatile(&mir.insns[8]) &&
           mir.insns[8].memory_size == 2 &&
           mir_machine_named_nonvolatile(&mir.insns[174]) &&
           mir.insns[174].memory_size == 4 &&
           mir_machine_named_nonvolatile(&mir.insns[190]) &&
           mir.insns[190].memory_size == 4 &&
           mir_machine_named_nonvolatile(&mir.insns[212]) &&
           mir.insns[212].memory_size == 4 &&
           mir_machine_named_nonvolatile(&mir.insns[327]) &&
           mir.insns[327].memory_size == 4;
}

